org.apache.pdfbox.cos.COSDocument.close() does not close the streams and causing therefore a growing memory leak. Supposed fix: 
public void close() throws IOException { 
// if (!closed) { 
// scratchFile.close(); 
// if (tmpFile != null) { 
// tmpFile.delete(); 
// } 
// closed = true; 
// } 
// begin Robert Scharpf 
closed = true; 
if (scratchFile != null) { 
try { 
scratchFile.close(); 
} catch (Exception e) { 
} 
} 
scratchFile = null; 
if (tmpFile != null) { 
try { 
tmpFile.delete(); 
} catch (Exception e) { 
} 
} 
tmpFile = null; 
List<COSObject> list = getObjectsByType(COSName.OBJ_STM); 
if (list != null) { 
for (COSObject objStream : list) { 
COSStream stream = (COSStream) objStream.getObject(); 
stream.close(); 
} 
} 
// end Robert Scharpf 
}

